<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: #0f172a;
    color: #e2e8f0;
    min-height: 100vh;
    padding: 32px 24px;
  }

  h1 {
    text-align: center;
    font-size: 1.8rem;
    font-weight: 700;
    letter-spacing: -0.5px;
    margin-bottom: 28px;
    color: #f8fafc;
  }

  .input-bar {
    display: flex;
    justify-content: center;
    gap: 10px;
    margin-bottom: 36px;
  }

  #new-card {
    width: 340px;
    padding: 10px 16px;
    border-radius: 8px;
    border: 1.5px solid #334155;
    background: #1e293b;
    color: #f1f5f9;
    font-size: 0.95rem;
    outline: none;
    transition: border-color 0.2s;
  }

  #new-card:focus { border-color: #6366f1; }
  #new-card::placeholder { color: #64748b; }

  #add-card {
    padding: 10px 20px;
    border-radius: 8px;
    border: none;
    background: #6366f1;
    color: #fff;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s, transform 0.1s;
  }

  #add-card:hover { background: #4f46e5; }
  #add-card:active { transform: scale(0.97); }

  .board {
    display: flex;
    gap: 20px;
    align-items: flex-start;
    max-width: 1100px;
    margin: 0 auto;
  }

  .column {
    flex: 1;
    background: #1e293b;
    border-radius: 14px;
    padding: 0 0 12px;
    min-height: 480px;
    display: flex;
    flex-direction: column;
    border: 1.5px solid #334155;
    transition: border-color 0.2s;
  }

  .column.drag-over {
    border-color: #6366f1;
    background: #1e2d45;
  }

  .col-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 18px 14px;
    border-bottom: 1.5px solid #334155;
  }

  .col-header h2 {
    font-size: 0.95rem;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
  }

  #col-todo .col-header h2 { color: #f59e0b; }
  #col-doing .col-header h2 { color: #38bdf8; }
  #col-done .col-header h2 { color: #4ade80; }

  .count {
    font-size: 0.78rem;
    font-weight: 700;
    background: #334155;
    color: #94a3b8;
    border-radius: 20px;
    padding: 2px 9px;
    min-width: 26px;
    text-align: center;
  }

  .card-container {
    flex: 1;
    padding: 12px 12px 0;
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-height: 60px;
  }

  .card {
    background: #0f172a;
    border: 1.5px solid #334155;
    border-radius: 10px;
    padding: 12px 14px;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
    cursor: grab;
    user-select: none;
    transition: transform 0.15s, box-shadow 0.15s, border-color 0.2s, opacity 0.2s;
    box-shadow: 0 1px 4px rgba(0,0,0,0.3);
  }

  .card:hover {
    border-color: #6366f1;
    box-shadow: 0 4px 14px rgba(99,102,241,0.25);
    transform: translateY(-1px);
  }

  .card.dragging {
    opacity: 0.4;
    cursor: grabbing;
  }

  .card-title {
    font-size: 0.9rem;
    line-height: 1.45;
    color: #e2e8f0;
    flex: 1;
    word-break: break-word;
  }

  .card-del {
    background: none;
    border: none;
    color: #64748b;
    font-size: 1.1rem;
    cursor: pointer;
    line-height: 1;
    padding: 0 2px;
    border-radius: 4px;
    flex-shrink: 0;
    transition: color 0.15s, background 0.15s;
  }

  .card-del:hover {
    color: #f87171;
    background: #2d1b1b;
  }

  @media (max-width: 700px) {
    .board { flex-direction: column; }
    #new-card { width: 220px; }
  }
</style>
</head>
<body>

<h1>📋 Kanban Board</h1>

<div class="input-bar">
  <input type="text" id="new-card" placeholder="New card title…" maxlength="200">
  <button id="add-card">+ Add Card</button>
</div>

<div class="board">
  <div class="column" id="col-todo">
    <div class="col-header">
      <h2>To Do</h2>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>

  <div class="column" id="col-doing">
    <div class="col-header">
      <h2>In Progress</h2>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>

  <div class="column" id="col-done">
    <div class="col-header">
      <h2>Done</h2>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>
</div>

<script>
  const STORAGE_KEY = 'kanban_v1';
  const columns = ['col-todo', 'col-doing', 'col-done'];
  let draggedCard = null;

  /* ---- Persistence ---- */
  function saveState() {
    const state = {};
    columns.forEach(colId => {
      const container = document.querySelector(`#${colId} .card-container`);
      state[colId] = Array.from(container.querySelectorAll('.card')).map(c => ({
        id: c.dataset.id,
        title: c.querySelector('.card-title').textContent
      }));
    });
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }

  function loadState() {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return;
    try {
      const state = JSON.parse(raw);
      columns.forEach(colId => {
        const cards = state[colId] || [];
        cards.forEach(({ id, title }) => createCard(title, colId, id));
      });
    } catch(e) { /* ignore corrupt data */ }
  }

  /* ---- Card creation ---- */
  let idCounter = Date.now();
  function uniqueId() { return 'card-' + (idCounter++); }

  function createCard(title, colId, existingId) {
    const id = existingId || uniqueId();
    const card = document.createElement('div');
    card.className = 'card';
    card.draggable = true;
    card.dataset.id = id;

    const titleEl = document.createElement('span');
    titleEl.className = 'card-title';
    titleEl.textContent = title;

    const delBtn = document.createElement('button');
    delBtn.className = 'card-del';
    delBtn.title = 'Delete card';
    delBtn.innerHTML = '&times;';
    delBtn.addEventListener('click', () => {
      card.remove();
      updateCount(colId);
      saveState();
    });

    card.appendChild(titleEl);
    card.appendChild(delBtn);

    /* Drag events */
    card.addEventListener('dragstart', e => {
      draggedCard = card;
      card.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', id);
    });
    card.addEventListener('dragend', () => {
      card.classList.remove('dragging');
      draggedCard = null;
    });

    const container = document.querySelector(`#${colId} .card-container`);
    container.appendChild(card);
    updateCount(colId);
  }

  /* ---- Count ---- */
  function updateCount(colId) {
    const col = document.getElementById(colId);
    const n = col.querySelectorAll('.card').length;
    col.querySelector('.count').textContent = n;
  }

  /* ---- Column drag-and-drop ---- */
  columns.forEach(colId => {
    const col = document.getElementById(colId);

    col.addEventListener('dragover', e => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      col.classList.add('drag-over');
    });

    col.addEventListener('dragleave', e => {
      // Only remove if leaving the column entirely
      if (!col.contains(e.relatedTarget)) {
        col.classList.remove('drag-over');
      }
    });

    col.addEventListener('drop', e => {
      e.preventDefault();
      col.classList.remove('drag-over');
      if (!draggedCard) return;

      const fromColEl = draggedCard.closest('.column');
      const fromColId = fromColEl ? fromColEl.id : null;

      const container = col.querySelector('.card-container');
      container.appendChild(draggedCard);

      if (fromColId && fromColId !== colId) {
        updateCount(fromColId);
      }
      updateCount(colId);
      saveState();
    });
  });

  /* ---- Add card button ---- */
  document.getElementById('add-card').addEventListener('click', () => {
    const input = document.getElementById('new-card');
    const title = input.value.trim();
    if (!title) return;
    createCard(title, 'col-todo');
    saveState();
    input.value = '';
    input.focus();
  });

  document.getElementById('new-card').addEventListener('keydown', e => {
    if (e.key === 'Enter') document.getElementById('add-card').click();
  });

  /* ---- Init ---- */
  loadState();
</script>
</body>
</html>
